<!doctype html>
<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>Sam Code — The IDE That Thinks With You</title>
    <link rel="icon" href="./1.png" type="image/png" />
    <link rel="preconnect" href="https://fonts.googleapis.com" />
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
    <link href="https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@400;500;600&family=Inter:wght@400;500;600;700;800;900&display=swap" rel="stylesheet" />
    <style>
      *,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
      :root{
        --bg:#09090b;
        --surface:#111113;
        --surface-2:#18181b;
        --surface-3:#1e1e22;
        --border:rgba(255,255,255,0.06);
        --border-hover:rgba(255,255,255,0.12);
        --text:#fafafa;
        --text-2:#a1a1aa;
        --text-3:#71717a;
        --accent:#a78bfa;
        --accent-dim:rgba(167,139,250,0.12);
        --green:#34d399;
        --green-dim:rgba(52,211,153,0.1);
        --amber:#fbbf24;
        --red:#f87171;
        --radius:12px;
        --radius-lg:20px;
        --font-sans:'Inter',system-ui,-apple-system,sans-serif;
        --font-mono:'JetBrains Mono',ui-monospace,monospace;
      }
      html{scroll-behavior:smooth}
      body{
        font-family:var(--font-sans);
        color:var(--text);
        background:var(--bg);
        min-height:100vh;
        overflow-x:hidden;
        -webkit-font-smoothing:antialiased;
      }
      a{color:inherit;text-decoration:none}
      .container{width:min(1120px,100% - 48px);margin:0 auto}

      /* NAV */
      .nav{
        position:sticky;top:0;z-index:100;
        background:rgba(9,9,11,0.8);
        backdrop-filter:blur(20px) saturate(1.4);
        border-bottom:1px solid var(--border);
      }
      .nav-inner{
        display:flex;align-items:center;justify-content:space-between;
        padding:16px 0;
      }
      .nav-brand{display:flex;align-items:center;gap:10px;font-weight:700;font-size:1.05rem}
      .nav-brand img{width:32px;height:32px;border-radius:8px}
      .nav-links{display:flex;gap:32px;font-size:0.875rem;color:var(--text-2)}
      .nav-links a:hover{color:var(--text)}
      .nav-cta{
        padding:8px 16px;border-radius:8px;font-size:0.85rem;font-weight:600;
        background:var(--text);color:var(--bg);
        transition:opacity .2s;
      }
      .nav-cta:hover{opacity:0.85}

      /* HERO */
      .hero{padding:100px 0 80px;position:relative}
      .hero::before{
        content:'';position:absolute;top:-200px;left:50%;transform:translateX(-50%);
        width:800px;height:600px;
        background:radial-gradient(ellipse,rgba(167,139,250,0.08) 0%,transparent 70%);
        pointer-events:none;
      }
      .hero-grid{
        display:grid;grid-template-columns:1fr 1fr;gap:64px;align-items:center;
        position:relative;z-index:1;
      }
      .hero-badge{
        display:inline-flex;align-items:center;gap:8px;
        padding:6px 14px;border-radius:99px;
        background:var(--accent-dim);border:1px solid rgba(167,139,250,0.2);
        font-size:0.8rem;font-weight:500;color:var(--accent);
        margin-bottom:24px;
      }
      .hero-badge::before{
        content:'';width:6px;height:6px;border-radius:50%;
        background:var(--accent);
        box-shadow:0 0 8px var(--accent);
      }
      .hero h1{
        font-size:clamp(2.8rem,5vw,4.2rem);
        font-weight:800;line-height:1.05;letter-spacing:-0.04em;
        margin-bottom:20px;
      }
      .hero h1 span{
        background:linear-gradient(135deg,var(--accent),#c4b5fd,var(--green));
        -webkit-background-clip:text;background-clip:text;color:transparent;
      }
      .hero-desc{
        font-size:1.1rem;line-height:1.7;color:var(--text-2);
        max-width:48ch;margin-bottom:32px;
      }
      .hero-actions{display:flex;gap:12px;flex-wrap:wrap}
      .btn{
        display:inline-flex;align-items:center;gap:8px;
        padding:14px 24px;border-radius:10px;font-weight:600;font-size:0.95rem;
        transition:all .2s ease;border:1px solid transparent;cursor:pointer;
      }
      .btn-primary{background:var(--accent);color:#09090b}
      .btn-primary:hover{background:#b89dfc;transform:translateY(-1px);box-shadow:0 8px 30px rgba(167,139,250,0.3)}
      .btn-ghost{border-color:var(--border-hover);color:var(--text-2)}
      .btn-ghost:hover{border-color:var(--accent);color:var(--accent)}

      /* TERMINAL PREVIEW */
      .terminal{
        background:var(--surface);
        border:1px solid var(--border);
        border-radius:var(--radius-lg);
        overflow:hidden;
        box-shadow:0 40px 100px rgba(0,0,0,0.5),0 0 0 1px rgba(255,255,255,0.03) inset;
      }
      .terminal-bar{
        display:flex;align-items:center;justify-content:space-between;
        padding:14px 18px;border-bottom:1px solid var(--border);
        background:var(--surface-2);
      }
      .terminal-dots{display:flex;gap:7px}
      .terminal-dots span{width:11px;height:11px;border-radius:50%}
      .terminal-dots .d-r{background:var(--red)}
      .terminal-dots .d-y{background:var(--amber)}
      .terminal-dots .d-g{background:var(--green)}
      .terminal-title{
        font-family:var(--font-mono);font-size:0.75rem;color:var(--text-3);
        display:flex;align-items:center;gap:6px;
      }
      .terminal-title img{width:16px;height:16px;border-radius:4px}
      .terminal-body{padding:24px;font-family:var(--font-mono);font-size:0.88rem;line-height:2}
      .terminal-body .ln{display:flex;gap:12px}
      .terminal-body .ln-num{color:var(--text-3);user-select:none;min-width:20px;text-align:right}
      .terminal-body .kw{color:#c084fc}
      .terminal-body .str{color:var(--green)}
      .terminal-body .fn{color:var(--amber)}
      .terminal-body .var{color:#e2e8f0}
      .terminal-body .br{color:var(--text-3)}
      .terminal-output{
        margin-top:16px;padding-top:16px;border-top:1px solid var(--border);
        color:var(--text-3);font-size:0.82rem;
      }
      .terminal-output .prompt{color:var(--green)}
      .terminal-output .result{color:var(--text-2);margin-top:4px}

      /* SECTIONS */
      .section{padding:80px 0}
      .section-label{
        display:inline-flex;align-items:center;gap:6px;
        font-size:0.75rem;font-weight:600;letter-spacing:0.08em;text-transform:uppercase;
        color:var(--accent);margin-bottom:12px;
      }
      .section-title{
        font-size:clamp(2rem,3.5vw,2.8rem);font-weight:800;
        letter-spacing:-0.03em;line-height:1.1;margin-bottom:16px;
      }
      .section-desc{
        font-size:1.05rem;color:var(--text-2);line-height:1.7;
        max-width:56ch;margin-bottom:48px;
      }

      /* FEATURES GRID */
      .features-grid{
        display:grid;grid-template-columns:repeat(3,1fr);gap:1px;
        background:var(--border);border-radius:var(--radius-lg);overflow:hidden;
        border:1px solid var(--border);
      }
      .feature{
        padding:32px;background:var(--surface);
        transition:background .2s;
      }
      .feature:hover{background:var(--surface-2)}
      .feature-icon{
        width:40px;height:40px;border-radius:10px;
        display:flex;align-items:center;justify-content:center;
        font-size:1.2rem;margin-bottom:16px;
        background:var(--accent-dim);border:1px solid rgba(167,139,250,0.15);
      }
      .feature h3{font-size:1rem;font-weight:700;margin-bottom:8px}
      .feature p{font-size:0.9rem;color:var(--text-2);line-height:1.6}

      /* AGENT SECTION */
      .agent-section{
        background:linear-gradient(180deg,var(--surface) 0%,var(--bg) 100%);
        border-top:1px solid var(--border);
        border-bottom:1px solid var(--border);
      }
      .agent-grid{
        display:grid;grid-template-columns:1fr 1fr;gap:64px;align-items:start;
      }
      .agent-info h2{
        font-size:clamp(2.2rem,4vw,3.2rem);font-weight:800;
        letter-spacing:-0.03em;line-height:1.05;margin-bottom:8px;
      }
      .agent-info h2 span{color:var(--accent)}
      .agent-subtitle{
        font-size:1rem;color:var(--accent);font-weight:500;margin-bottom:20px;
      }
      .agent-info>p:last-of-type{
        font-size:1.05rem;color:var(--text-2);line-height:1.7;margin-bottom:32px;
      }
      .agent-features{display:grid;gap:16px}
      .agent-feat{
        display:flex;gap:14px;padding:16px;border-radius:var(--radius);
        border:1px solid var(--border);background:rgba(255,255,255,0.02);
        transition:border-color .2s,background .2s;
      }
      .agent-feat:hover{border-color:var(--border-hover);background:var(--surface)}
      .agent-feat-icon{
        width:36px;height:36px;border-radius:8px;flex-shrink:0;
        display:flex;align-items:center;justify-content:center;
        background:var(--green-dim);color:var(--green);font-size:1rem;
      }
      .agent-feat h4{font-size:0.92rem;font-weight:600;margin-bottom:4px}
      .agent-feat p{font-size:0.84rem;color:var(--text-3);line-height:1.5}

      .agent-visual{
        position:sticky;top:100px;
        background:var(--surface);border:1px solid var(--border);
        border-radius:var(--radius-lg);overflow:hidden;
        box-shadow:0 30px 80px rgba(0,0,0,0.4);
      }
      .agent-visual-bar{
        padding:12px 16px;border-bottom:1px solid var(--border);
        display:flex;align-items:center;gap:8px;
        font-family:var(--font-mono);font-size:0.75rem;color:var(--text-3);
      }
      .agent-visual-bar::before{
        content:'';width:8px;height:8px;border-radius:50%;
        background:var(--green);box-shadow:0 0 6px var(--green);
      }
      .agent-visual-body{padding:20px;font-family:var(--font-mono);font-size:0.82rem;line-height:1.8}
      .av-line{display:flex;gap:8px;margin-bottom:2px}
      .av-prompt{color:var(--accent);flex-shrink:0}
      .av-cmd{color:var(--text)}
      .av-comment{color:var(--text-3);font-style:italic}
      .av-success{color:var(--green)}
      .av-warn{color:var(--amber)}

      /* DOWNLOAD */
      .download-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}
      .dl-card{
        padding:28px;border-radius:var(--radius-lg);
        border:1px solid var(--border);background:var(--surface);
        transition:border-color .2s,transform .2s;
        text-align:center;
      }
      .dl-card:hover{border-color:var(--border-hover);transform:translateY(-2px)}
      .dl-icon{
        width:56px;height:56px;border-radius:14px;margin:0 auto 16px;
        display:flex;align-items:center;justify-content:center;
        background:var(--surface-3);border:1px solid var(--border);
        font-size:1.6rem;
      }
      .dl-card h3{font-size:1.1rem;font-weight:700;margin-bottom:4px}
      .dl-card p{font-size:0.85rem;color:var(--text-3);margin-bottom:20px}
      .dl-btn{
        display:block;width:100%;padding:12px;border-radius:10px;
        background:var(--surface-3);border:1px solid var(--border);
        font-weight:600;font-size:0.9rem;color:var(--text);
        transition:all .2s;
      }
      .dl-btn:hover{background:var(--accent);color:var(--bg);border-color:var(--accent)}

      /* FOOTER */
      .footer{
        padding:48px 0;border-top:1px solid var(--border);
        margin-top:40px;
      }
      .footer-inner{
        display:flex;align-items:center;justify-content:space-between;
        flex-wrap:wrap;gap:20px;
      }
      .footer-brand{display:flex;align-items:center;gap:10px;font-weight:600;font-size:0.95rem}
      .footer-brand img{width:28px;height:28px;border-radius:6px}
      .footer-links{display:flex;gap:24px;font-size:0.85rem;color:var(--text-3)}
      .footer-links a:hover{color:var(--text)}
      .footer-copy{font-size:0.82rem;color:var(--text-3)}

      /* RESPONSIVE */
      @media(max-width:900px){
        .hero-grid,.agent-grid{grid-template-columns:1fr;gap:40px}
        .features-grid{grid-template-columns:1fr}
        .download-grid{grid-template-columns:1fr}
        .nav-links{display:none}
        .agent-visual{position:static}
        .footer-inner{flex-direction:column;text-align:center}
      }
    </style>
  </head>
  <body>

    <header class="nav">
      <div class="container nav-inner">
        <a class="nav-brand" href="#top">
          <img src="./1.png" alt="Sam Code" />
          <span>Sam Code</span>
        </a>
        <nav class="nav-links">
          <a href="#features">Features</a>
          <a href="#agent">Agent</a>
          <a href="#download">Download</a>
        </nav>
        <a class="nav-cta" href="#download">Get Started</a>
      </div>
    </header>

    <main id="top" class="hero">
      <div class="container hero-grid">
        <div>
          <div class="hero-badge">Now available on all platforms</div>
          <h1>The IDE that<br/><span>thinks with you.</span></h1>
          <p class="hero-desc">
            A lightweight desktop editor with a built-in AI agent that executes step-by-step, 
            recovers from errors, and works with any LLM provider you choose.
          </p>
          <div class="hero-actions">
            <a class="btn btn-primary" href="#download">
              <svg width="16" height="16" viewBox="0 0 16 16" fill="none"><path d="M8 1v10M4 8l4 4 4-4M2 14h12" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg>
              Download Sam Code
            </a>
            <a class="btn btn-ghost" href="#agent">Meet Sam →</a>
          </div>
        </div>

        <div class="terminal">
          <div class="terminal-bar">
            <div class="terminal-dots">
              <span class="d-r"></span><span class="d-y"></span><span class="d-g"></span>
            </div>
            <div class="terminal-title">
              <img src="./1.png" alt="" /> sam-code — main.js
            </div>
            <div></div>
          </div>
          <div class="terminal-body">
            <div class="ln"><span class="ln-num">1</span><span><span class="kw">const</span> <span class="var">editor</span> = <span class="str">'Sam Code'</span>;</span></div>
            <div class="ln"><span class="ln-num">2</span><span><span class="kw">const</span> <span class="var">assistant</span> = <span class="str">'Sam'</span>;</span></div>
            <div class="ln"><span class="ln-num">3</span><span><span class="kw">const</span> <span class="var">platforms</span> = <span class="br">[</span><span class="str">'Windows'</span>, <span class="str">'macOS'</span>, <span class="str">'Linux'</span><span class="br">]</span>;</span></div>
            <div class="ln"><span class="ln-num">4</span><span></span></div>
            <div class="ln"><span class="ln-num">5</span><span>console.<span class="fn">log</span><span class="br">(</span><span class="var">editor</span>, <span class="var">assistant</span>, <span class="var">platforms</span><span class="br">)</span>;</span></div>
            <div class="terminal-output">
              <div class="prompt">▸ Output</div>
              <div class="result">Sam Code Sam [ 'Windows', 'macOS', 'Linux' ]</div>
            </div>
          </div>
        </div>
      </div>
    </main>

    <section class="section" id="features">
      <div class="container">
        <div class="section-label">Features</div>
        <h2 class="section-title">Everything you need.<br/>Nothing you don't.</h2>
        <p class="section-desc">
          Built from the ground up for speed and clarity. No bloated feature set—just the tools 
          that matter for modern development workflows.
        </p>
        <div class="features-grid">
          <div class="feature">
            <div class="feature-icon">⚡</div>
            <h3>Instant startup</h3>
            <p>Launches in under a second. No heavy initialization, no loading spinners.</p>
          </div>
          <div class="feature">
            <div class="feature-icon">🎨</div>
            <h3>Monaco editor</h3>
            <p>The same engine that powers VS Code. Full syntax highlighting, IntelliSense, and theming.</p>
          </div>
          <div class="feature">
            <div class="feature-icon">📁</div>
            <h3>Integrated file explorer</h3>
            <p>Navigate your project tree without leaving the editor. Drag, drop, rename inline.</p>
          </div>
          <div class="feature">
            <div class="feature-icon">⌨️</div>
            <h3>Built-in terminal</h3>
            <p>Run commands, execute scripts, and see output in a docked terminal pane.</p>
          </div>
          <div class="feature">
            <div class="feature-icon">🧩</div>
            <h3>Marketplace</h3>
            <p>Extend functionality with community plugins and language packs.</p>
          </div>
          <div class="feature">
            <div class="feature-icon">🔒</div>
            <h3>Local-first</h3>
            <p>Your files stay on your machine. No telemetry, no cloud sync required.</p>
          </div>
        </div>
      </div>
    </section>

    <section class="section agent-section" id="agent">
      <div class="container">
        <div class="agent-grid">
          <div class="agent-info">
            <div class="section-label">AI Agent</div>
            <h2>Meet <span>Sam</span></h2>
            <p class="agent-subtitle">Your independent AI coding agent</p>
            <p>
              Sam isn't a copilot that suggests completions. It's an autonomous agent that reads 
              your workspace, plans multi-step tasks, executes terminal commands one at a time, 
              and recovers from errors automatically. Bring your own API key—works with OpenAI, 
              Anthropic, Google, Ollama, or any OpenRouter model.
            </p>
            <div class="agent-features">
              <div class="agent-feat">
                <div class="agent-feat-icon">✓</div>
                <div>
                  <h4>Step-by-step execution</h4>
                  <p>Each command runs with your approval. You see the output before the next step.</p>
                </div>
              </div>
              <div class="agent-feat">
                <div class="agent-feat-icon">↻</div>
                <div>
                  <h4>Automatic error recovery</h4>
                  <p>When a command fails, Sam analyzes the error and proposes a corrected version.</p>
                </div>
              </div>
              <div class="agent-feat">
                <div class="agent-feat-icon">⚙</div>
                <div>
                  <h4>Any LLM backend</h4>
                  <p>No vendor lock-in. Use OpenRouter, Ollama, Google AI, OpenAI, or your own endpoint.</p>
                </div>
              </div>
              <div class="agent-feat">
                <div class="agent-feat-icon">💬</div>
                <div>
                  <h4>Chat + Agent modes</h4>
                  <p>Toggle between conversational Q&A and autonomous task execution seamlessly.</p>
                </div>
              </div>
            </div>
          </div>

          <div class="agent-visual">
            <div class="agent-visual-bar">Sam Agent — active session</div>
            <div class="agent-visual-body">
              <div class="av-line"><span class="av-prompt">sam ›</span><span class="av-cmd">Analyzing project structure...</span></div>
              <div class="av-line"><span class="av-comment">// Found: package.json, src/, README.md</span></div>
              <div class="av-line"><span class="av-prompt">sam ›</span><span class="av-cmd">npm install react@latest</span></div>
              <div class="av-line"><span class="av-success">✓ Installed successfully (2.3s)</span></div>
              <div class="av-line"><span class="av-prompt">sam ›</span><span class="av-cmd">npx tsc --noEmit</span></div>
              <div class="av-line"><span class="av-warn">⚠ Error: Cannot find module './utils'</span></div>
              <div class="av-line"><span class="av-prompt">sam ›</span><span class="av-cmd">Creating src/utils.ts...</span></div>
              <div class="av-line"><span class="av-success">✓ Fixed. Re-running check...</span></div>
              <div class="av-line"><span class="av-success">✓ All checks passed</span></div>
            </div>
          </div>
        </div>
      </div>
    </section>

    <section class="section" id="download">
      <div class="container">
        <div class="section-label">Download</div>
        <h2 class="section-title">Get Sam Code</h2>
        <p class="section-desc">
          Available for all major platforms. Same editor, same agent, same experience everywhere.
        </p>
        <div class="download-grid">
          <div class="dl-card">
            <div class="dl-icon">🪟</div>
            <h3>Windows</h3>
            <p>64-bit installer (.exe)</p>
            <a class="dl-btn" href="https://sam-code.onrender.com/download/sam-code-1.0.0-setup.exe" target="_blank" rel="noopener">Download</a>
          </div>
          <div class="dl-card">
            <div class="dl-icon">🍎</div>
            <h3>macOS</h3>
            <p>Universal (Intel + Apple Silicon)</p>
            <a class="dl-btn" href="https://sam-code.onrender.com/download/sam-code-1.0.0.dmg" target="_blank" rel="noopener">Download</a>
          </div>
          <div class="dl-card">
            <div class="dl-icon">🐧</div>
            <h3>Linux</h3>
            <p>AppImage (x86_64)</p>
            <a class="dl-btn" href="https://sam-code.onrender.com/download/sam-code-1.0.0.AppImage" target="_blank" rel="noopener">Download</a>
          </div>
        </div>
      </div>
    </section>

    <footer class="footer">
      <div class="container footer-inner">
        <div class="footer-brand">
          <img src="./1.png" alt="Sam Code" />
          <span>Sam Code</span>
        </div>
        <div class="footer-links">
          <a href="#features">Features</a>
          <a href="#agent">Agent</a>
          <a href="#download">Download</a>
          <a href="https://github.com/Houssemeddine-mag/Sam-Code" target="_blank" rel="noopener">GitHub</a>
        </div>
        <div class="footer-copy">© 2025 Sam Code. Built for developers.</div>
      </div>
    </footer>

